```python
def rle_decode(s: str) -> str:
    res = []
    i = 0
    n = len(s)

    while i < n:
        if s[i] == '#':
            # '#' must be preceded by a character
            if not res:
                raise ValueError("Marker '#' must be preceded by a character.")

            char = res.pop()
            i += 1
            start = i
            while i < n and s[i].isdigit():
                i += 1

            # Must be followed by at least one digit
            if start == i:
                raise ValueError("Marker '#' must be followed by at least one digit.")

            count = int(s[start:i])
            if count < 4:
                raise ValueError("Run count must be at least 4.")

            res.append(char * count)
        else:
            res.append(s[i])
            i += 1

    return "".join(res)
